package com.logatron.catalog.application;
import com.logatron.auth.application.*;import com.logatron.auth.domain.PlatformRole;import com.logatron.catalog.domain.CatalogEnums.*;import com.logatron.catalog.persistence.*;import org.junit.jupiter.api.Test;import org.springframework.security.oauth2.jwt.Jwt;import java.time.Instant;import java.util.*;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
class CatalogQueryServiceTest{@Test void projectListUsesOnlyEffectiveScopeIds(){var auth=mock(AuthorizationService.class);var projects=mock(ProjectRepository.class);var environments=mock(EnvironmentRepository.class);var servers=mock(ServerRepository.class);var services=mock(ServiceRepository.class);var instances=mock(ServiceInstanceRepository.class);var sources=mock(LogSourceRepository.class);UUID allowed=UUID.randomUUID(),denied=UUID.randomUUID();var jwt=Jwt.withTokenValue("t").header("alg","none").subject("developer").issuedAt(Instant.now()).expiresAt(Instant.now().plusSeconds(60)).build();var scope=new EffectiveScope(false,Map.of(allowed,new EffectiveScope.ProjectScope(allowed,Set.of(PlatformRole.DEVELOPER),Set.of(),Map.of(),false)));when(auth.resolveScope(jwt)).thenReturn(scope);when(projects.findAllByIdInOrderByName(Set.of(allowed))).thenReturn(List.of(new ProjectEntity(allowed,null,"allowed","Allowed",Classification.INTERNAL,Status.ACTIVE)));when(environments.findByProjectIdOrderByCode(allowed)).thenReturn(List.of());var service=new CatalogQueryService(auth,projects,environments,servers,services,instances,sources);assertThat(service.projects(jwt)).extracting(v->v.id()).containsExactly(allowed).doesNotContain(denied);verify(projects).findAllByIdInOrderByName(Set.of(allowed));}}
